   const original=engine.ctx.createBuffer(2,sr*duration,sr),stems=Array.from({length:4},()=>engine.ctx.createBuffer(2,sr*duration,sr));
   for(let stem=0;stem<4;stem++){const selected=cfg.mode==='vocal'?stem===0:stem>0,amplitude=selected?(cfg.mode==='vocal'?.12:.04):(cfg.mode==='vocal'?.04:.12),channel=selected?0:1,data=stems[stem].getChannelData(channel),mix=original.getChannelData(channel);for(let n=0;n<data.length;n++){const t=n/sr;data[n]=amplitude*Math.sin(2*Math.PI*(selected?220*t+10*t*t:550*t));mix[n]+=data[n];}}
