   const factor=2**(cfg.semitones/12)*(cfg.keylock?1:1.08),window=(name,s,from,to)=>{const p=s.selectedPosition+s.velocity*(from+to)/2;mode.windows.push({name,from:s.audioTime-engine.recordStarted+from,to:s.audioTime-engine.recordStarted+to,expectedSelectedHz:(220+20*p)*factor,expectedComplementHz:550*factor});};
